import math

# Extract parameters
P = assign.get('prime_power')
e = assign.get('offset')
n = assign.get('term_index')
M = assign.get('modulus')

# Basic validation
if not isinstance(P, int) or not isinstance(e, int) or not isinstance(n, int) or not isinstance(M, int):
    # invalid types
    return (False, None)
if P <= 1 or e < 0 or n <= 0 or M <= 1:
    # invalid ranges
    return (False, None)

# Factor P as an odd prime power p^k
def is_prime(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    r = int(math.isqrt(x))
    for a in range(3, r+1, 2):
        if x % a == 0:
            return False
    return True

# Find smallest prime factor
sp = None
for a in range(2, int(math.isqrt(P)) + 1):
    if P % a == 0:
        sp = a
        break
if sp is None:
    # P itself prime; we require k >= 2
    # invalid instance
    return (False, None)
# Check that P is a pure power of sp
kk = 0
tmp = P
while tmp % sp == 0:
    tmp //= sp
    kk += 1
if tmp != 1:
    # Not a prime power
    return (False, None)
p = sp
k = kk
if not is_prime(p) or p % 2 == 0 or k < 2:
    # Must be odd prime power with exponent >= 2
    return (False, None)

# Normalize offset into [0, P-1]
e = e % P
if e == 0:
    # We need e not divisible by p to ensure two distinct roots and non-vanishing derivative
    return (False, None)
if math.gcd(e, p) != 1:
    # e divisible by p would complicate roots; disallow
    return (False, None)

# Ensure non-trivial difficulty: P reasonably large and n large
if P < 121 or n < 1000 or M < 1000:
    # enforce harder-than-seed instances
    return (False, None)

# Solve m^2 \equiv e (mod p) by brute force (p is small), then Hensel-lift to mod p^k.
e_mod_p = e % p
roots_mod_p = []
for t in range(1, p):  # exclude 0 deliberately
    if (t * t) % p == e_mod_p:
        roots_mod_p.append(t)
        if len(roots_mod_p) == 2:
            break
if len(roots_mod_p) != 2:
    # offset must be a quadratic residue modulo p with two roots
    return (False, None)

r0 = roots_mod_p[0]

def egcd(a, b):
    x0, x1, y0, y1 = 1, 0, 0, 1
    while b:
        q = a // b
        a, b = b, a - q * b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return a, x0, y0

def inv_mod(a, m):
    g, x, _ = egcd(a % m, m)
    if g != 1:
        return None
    return x % m

# Hensel lifting from mod p to mod p^k
r = r0
mod = p
for _ in range(1, k):
    # r^2 \equiv e (mod mod). Seek s in Z/pZ such that (r + s*mod)^2 \equiv e (mod mod*p)
    # Dividing the congruence difference by 'mod' yields: q + 2*r*s \equiv 0 (mod p), where q = (r^2 - e)/mod.
    diff = r * r - e
    if diff % mod != 0:
        # should be divisible by current modulus
        return (False, None)
    q = diff // mod
    inv = inv_mod((2 * r) % p, p)
    if inv is None:
        # derivative 2r must be invertible mod p
        return (False, None)
    s = (-q * inv) % p
    r = r + s * mod
    mod *= p
r %= P
r_alt = (-r) % P

# Order the two residue classes to form the merged increasing sequence.
a = r if r <= r_alt else r_alt
b = r_alt if r <= r_alt else r

# The allowed m form two arithmetic progressions with common difference P: a + tP and b + tP.
# Sorted merging yields: m_{2t+1} = a + tP, m_{2t+2} = b + tP.
if n % 2 == 1:
    t = (n - 1) // 2
    m = a + t * P
else:
    t = (n - 2) // 2
    m = b + t * P

x = m * m - e
answer = x % M
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

